"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowDownToLine, ArrowRight, Check, ChevronRight, CircleHelp, FileCheck2, Layers3, Mail, RefreshCw, ShieldCheck, Upload, Users } from "lucide-react";
import type { AcquisitionState, BuyerMatch, Channel, Command, Download, GateName, ImportInput, ImportPreview, Lead, Role, Summary } from "@/src/acquisition/types";
import { DeskForm, Empty, Field, Fold, Money, Panel, Pill, dateValue, humanize, listValue, numberValue, prettyDate, textValue, type FieldSpec } from "./acquisition-ui";

type Workspace = { id: string; name: string; role: Role };
type Payload = { state: AcquisitionState; version: number; summary: Summary; workspace?: Workspace; role?: Role; result?: unknown };
type Tab = "today" | "import" | "leads" | "batches" | "deals" | "readiness";
const TABS: { id: Tab; title: string; icon: typeof Layers3 }[] = [
  { id: "today", title: "Today", icon: Layers3 }, { id: "import", title: "Import", icon: Upload },
  { id: "leads", title: "Seller leads", icon: Users }, { id: "batches", title: "Mail & calls", icon: Mail },
  { id: "deals", title: "Contracts & buyers", icon: FileCheck2 }, { id: "readiness", title: "Readiness", icon: ShieldCheck },
];
const GATES: { id: GateName; label: string; need: string }[] = [
  { id: "counsel", label: "Counsel review", need: "Approved contract and assignment disclosure references, approving person, scope and review date." },
  { id: "channel_policy", label: "Mail & manual calling policy", need: "Reviewed channel rules, business identity, contact disclosures and manual calling procedure." },
  { id: "data_provenance", label: "Data source permission", need: "Export source, authorized account/entity, permitted use and dated evidence reference." },
  { id: "suppression_ops", label: "Suppression handling", need: "Verified scrub procedure, opt-out handling and the shared suppression process." },
  { id: "title_escrow", label: "Title & escrow", need: "Title/escrow contact and confirmation that they can support this assignment process." },
  { id: "technical", label: "Release verification", need: "Verified release/test reference for this hosted workspace and backup/recovery procedure." },
  { id: "launch_authorization", label: "Launch authorization", need: "Operator authorization for the reviewed manual workflow, budget and initial scope." },
  { id: "nod_counsel", label: "Pre-foreclosure review", need: "Separate counsel approval for leads with a notice of default; only applies to those leads." },
];
const SOURCE_COLUMNS = "county,apn,address,city,zip,owner_name,mailing_address,phone,email,property_type,estimated_value,equity_pct,tax_delinquent_years,years_owned,nod,vacant,absentee,inherited,code_violations,notes\n";
const channelLabel = (channel: Channel) => channel === "mail" ? "Direct mail" : "Manual calling";
const refField: FieldSpec = { name: "reference", label: "Evidence reference", required: true, hint: "Document name, secure link or receipt ID you can retrieve later." };
const evidenceField: FieldSpec = { name: "evidence", label: "Review evidence", required: true, type: "textarea", hint: "Identify the reviewer, approved scope and the source document. Do not paste secrets." };
const occurredField: FieldSpec = { name: "occurredAt", label: "Actual date & time", required: true, type: "datetime-local", hint: "Enter the real event time in your device's local timezone." };
const opt = (value: string, label?: string) => ({ value, label: label ?? humanize(value) });
const optionalNumber = (d: FormData, name: string) => textValue(d, name) === "" ? null : numberValue(d, name);
function downloadFile(file: Download) {
  const url = URL.createObjectURL(new Blob([file.content], { type: file.mimeType }));
  const anchor = document.createElement("a"); anchor.href = url; anchor.download = file.filename; anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
const isDownload = (value: unknown): value is Download => !!value && typeof value === "object" && "content" in value && "filename" in value && "mimeType" in value;

export function AcquisitionDesk() {
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [workspaceId, setWorkspaceId] = useState("");
  const [payload, setPayload] = useState<Payload | null>(null);
  const [tab, setTab] = useState<Tab>("today");
  const [busy, setBusy] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [selected, setSelected] = useState<string[]>([]);
  const [focusedLeadId, setFocusedLeadId] = useState("");
  const [search, setSearch] = useState("");
  const [preview, setPreview] = useState<ImportPreview | null>(null);
  const [importInput, setImportInput] = useState<ImportInput | null>(null);
  const [csv, setCsv] = useState("");
  const [fileName, setFileName] = useState("");
  const [matches, setMatches] = useState<{ contractId: string; buyers: BuyerMatch[] } | null>(null);
  const [packetBuyers, setPacketBuyers] = useState<string[]>([]);
  const [receiptBatchId, setReceiptBatchId] = useState("");
  const [receiptPacketId, setReceiptPacketId] = useState("");
  const workspaceRef = useRef(workspaceId);
  workspaceRef.current = workspaceId;

  useEffect(() => {
    const controller = new AbortController();
    (async () => {
      try {
        const response = await fetch("/api/workspaces", { cache: "no-store", signal: controller.signal });
        const data = await response.json();
        if (!response.ok) throw new Error(data.error || "Could not load your workspaces.");
        const list = data.workspaces as Workspace[];
        setWorkspaces(list);
        let preferred = "";
        try { preferred = localStorage.getItem("sangam.workspace") ?? ""; } catch { /* Storage is optional. */ }
        setWorkspaceId(list.find(item => item.id === preferred)?.id ?? list[0]?.id ?? "");
        if (!list.length) setBusy(false);
      } catch (cause) { if (!controller.signal.aborted) { setError(cause instanceof Error ? cause.message : "Could not load workspaces."); setBusy(false); } }
    })();
    return () => controller.abort();
  }, []);

  const reload = useCallback(async (id: string, signal?: AbortSignal) => {
    if (!id) return;
    setBusy(true); setError("");
    try {
      const response = await fetch(`/api/acquisition?workspaceId=${encodeURIComponent(id)}`, { cache: "no-store", signal });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Could not load the acquisition desk.");
      if (workspaceRef.current === id) setPayload(data as Payload);
    } catch (cause) { if (!signal?.aborted && workspaceRef.current === id) setError(cause instanceof Error ? cause.message : "Could not load the desk."); }
    finally { if (!signal?.aborted && workspaceRef.current === id) setBusy(false); }
  }, []);

  useEffect(() => {
    if (!workspaceId) return;
    setPayload(null); setSelected([]); setFocusedLeadId(""); setPreview(null); setImportInput(null); setCsv(""); setFileName(""); setMatches(null); setPacketBuyers([]); setNotice(""); setReceiptBatchId(""); setReceiptPacketId("");
    try { localStorage.setItem("sangam.workspace", workspaceId); } catch { /* Storage is optional. */ }
    const controller = new AbortController(); void reload(workspaceId, controller.signal);
    return () => controller.abort();
  }, [workspaceId, reload]);

  async function command(value: Command, success = "Saved. The workspace record is up to date."): Promise<unknown> {
    if (!payload || busy) return undefined;
    const targetId = workspaceId;
    setBusy(true); setError(""); setNotice("");
    try {
      const response = await fetch("/api/acquisition", { method: "POST", headers: { "Content-Type": "application/json" }, cache: "no-store", body: JSON.stringify({ workspaceId: targetId, version: payload.version, command: value }) });
      const data = await response.json();
      if (!response.ok) throw new Error(response.status === 409 ? "This workspace changed in another session. Refresh, check the latest record, then submit again." : data.error || "The request could not be completed.");
      if (workspaceRef.current !== targetId) return undefined;
      setPayload(previous => ({ ...previous, ...data } as Payload));
      setNotice(success);
      if (isDownload(data.result)) downloadFile(data.result);
      return data.result;
    } catch (cause) { setError(cause instanceof Error ? cause.message : "The request could not be completed."); return undefined; }
    finally { setBusy(false); }
  }

  const state = payload?.state;
  const summary = payload?.summary;
  const workspace = workspaces.find(item => item.id === workspaceId);
  const reviewer = (payload?.role ?? workspace?.role) !== "operator";
  const focused = state?.leads.find(lead => lead.id === focusedLeadId);
  const receiptBatch = state?.batches.find(batch => batch.id === receiptBatchId);
  const receiptPacket = state?.packets.find(packet => packet.id === receiptPacketId);
  const checked = (id: string) => selected.includes(id);
  function toggle(id: string) { setSelected(ids => ids.includes(id) ? ids.filter(value => value !== id) : [...ids, id]); }
  const approvedTemplates = state?.templates.filter(item => item.status === "approved") ?? [];
  const filteredLeads = state?.leads.filter(lead => `${lead.ownerName} ${lead.address} ${lead.apn} ${lead.zip}`.toLowerCase().includes(search.toLowerCase())) ?? [];
  const nextGate = GATES.find(gate => gate.id === summary?.nextBlockedGate);
  const selectedLeads = state?.leads.filter(lead => selected.includes(lead.id)) ?? [];
  const leadName = (id: string) => state?.leads.find(lead => lead.id === id)?.address ?? id;
  const buyerName = (id: string) => state?.buyers.find(buyer => buyer.id === id)?.name ?? id;
  const contractName = (id: string) => { const contract = state?.contracts.find(item => item.id === id); return contract ? leadName(contract.leadId) : id; };
  const contractOptions = state?.contracts.filter(contract => !contract.termination).map(contract => opt(contract.id, leadName(contract.leadId))) ?? [];

  return <div className="acq-desk" aria-busy={busy}>
    <header className="acq-heading"><div><p className="acq-eyebrow">INLAND EMPIRE · RIVERSIDE + SAN BERNARDINO</p><h1>Acquisition</h1><p className="acq-subtitle">From the first seller lead to a signed assignment.</p></div><div className="acq-heading-tools"><Pill tone="good"><span className="acq-dot" />Manual operations</Pill><button className="acq-icon-button" onClick={() => void reload(workspaceId)} disabled={busy || !workspaceId} aria-label="Refresh workspace"><RefreshCw size={16} className={busy ? "animate-spin" : ""} /></button></div></header>
    <div className="acq-workspace-bar"><label htmlFor="acq-workspace">Workspace</label><select id="acq-workspace" value={workspaceId} disabled={busy} onChange={event => setWorkspaceId(event.target.value)}><option value="" disabled>Select workspace</option>{workspaces.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select>{workspace && <Pill>{workspace.role}</Pill>}<span className="acq-workspace-note">Mail and calls are carried out by you. Automatic sending is disabled.</span></div>
    {error && <div className="acq-alert acq-alert-error" role="alert"><strong>Action needed</strong><p>{error}</p><button className="acq-text-button" disabled={busy} onClick={() => void reload(workspaceId)}>Refresh workspace</button></div>}
    {notice && <div className="acq-alert acq-alert-success" role="status"><Check size={17} /><p>{notice}</p><button onClick={() => setNotice("")} aria-label="Dismiss notification">×</button></div>}
    {!state || !summary ? <div className="acq-panel"><Empty title={busy ? "Opening your workspace" : "Workspace access is required"}>{busy ? "Loading the latest evidence and activity." : "An administrator must provision a workspace and add your signed-in user as a member. No seller data is visible until access is granted."}</Empty></div> : <>
      <nav className="acq-tabs" aria-label="Acquisition sections">{TABS.map(item => <button key={item.id} onClick={() => setTab(item.id)} aria-current={tab === item.id ? "page" : undefined} className={tab === item.id ? "active" : ""}><item.icon size={15} />{item.title}{item.id === "leads" && <span>{state.leads.length}</span>}</button>)}</nav>

      {tab === "today" && <div className="acq-stack">
        <div className="acq-mission"><div><p className="acq-eyebrow">90-DAY PILOT</p><h2>{summary.launchedAt ? `Day ${summary.day} · ${summary.daysRemaining} days remaining` : "Ready the first batch. Start with evidence."}</h2><p>{summary.launchedAt ? `The clock began with an actual recorded touch on ${prettyDate(summary.launchedAt)}.` : "The 90-day clock starts when you record the first actual touch. Downloads and practice records do not start it."}</p></div><div className="acq-mission-target"><strong>{summary.progress.contracts}<span> / {summary.targets.contracts}</span></strong><span>signed contracts</span></div></div>
        <div className="acq-stats"><Metric label="Unique sellers touched" value={summary.progress.leads} goal={summary.targets.leads} /><Metric label="Offers made" value={summary.progress.offers} goal={summary.targets.offers} /><Metric label="Conversations" value={summary.progress.conversations} /><Metric label="Assignment fees collected" value={<Money value={summary.progress.assignmentFees} />} /></div>
        <div className="acq-columns"><Panel title="Your next step" description="Readiness is checked again whenever you export.">
          <div className="acq-next"><ShieldCheck size={22} /><div><h3>{nextGate ? nextGate.label : "Prepare a reviewed manual batch"}</h3><p>{nextGate ? nextGate.need : "Choose eligible sellers, a reviewed template and a channel. Review the exact recipients and content before approval."}</p><button className="acq-text-button" onClick={() => setTab(nextGate ? "readiness" : "batches")}>{nextGate ? "Review gate evidence" : "Prepare mail or calls"}<ArrowRight size={14} /></button></div></div>
          <div className="acq-ready-grid"><div><strong>{summary.realLeads}</strong><span>real seller leads</span></div><div><strong>{summary.mailReady}</strong><span>ready for mail</span></div><div><strong>{summary.callReady}</strong><span>ready for calls now</span></div></div>
        </Panel><Panel title="At a glance" description="Practice records stay outside real results."><dl className="acq-facts"><div><dt>Scored 8 or higher</dt><dd>{summary.scoreQualified}</dd></div><div><dt>Reviewed templates</dt><dd>{summary.readiness.approvedTemplates}</dd></div><div><dt>Appointments</dt><dd>{summary.progress.appointments}</dd></div><div><dt>Recorded spend</dt><dd><Money value={summary.progress.spend} /></dd></div><div><dt>Cost per conversation</dt><dd><Money value={summary.costPer.conversation} /></dd></div><div><dt>Cost per offer</dt><dd><Money value={summary.costPer.offer} /></dd></div><div><dt>Cost per contract</dt><dd><Money value={summary.costPer.contract} /></dd></div><div><dt>Practice leads</dt><dd>{summary.syntheticLeads}</dd></div><div><dt>Automatic outbound</dt><dd><Pill>Disabled</Pill></dd></div></dl></Panel></div>
        <div className="acq-columns"><Panel title="Follow-ups due" description="Prepare another approved batch when a follow-up is due.">{summary.followUps.length ? <div className="acq-list">{summary.followUps.slice(0, 20).map(item => <button key={item.leadId} className="acq-list-row" onClick={() => { setFocusedLeadId(item.leadId); setTab("leads"); }}><span><strong>{item.ownerName}</strong><small>{prettyDate(item.dueAt)}</small></span><ChevronRight size={16} /></button>)}</div> : <Empty title="No follow-ups due">Actual touch history will create the follow-up queue.</Empty>}</Panel><Panel title="Buyer alerts due" description="Contracted deals need a manual buyer alert within 24 hours.">{summary.buyerAlertsDue.length ? <div className="acq-list">{summary.buyerAlertsDue.map(item => <button key={item.contractId} className="acq-list-row" onClick={() => setTab("deals")}><span><strong>{contractName(item.contractId)}</strong><small>{item.delivered} of {item.required} delivered · due {prettyDate(item.dueAt)}</small></span><ChevronRight size={16} /></button>)}</div> : <Empty title="No buyer alerts due">Signed contracts and actual delivery receipts will appear here.</Empty>}</Panel></div>
        <Panel title="Operating spend" description="Keep subscriptions, data and setup costs alongside recorded deal activity."><Fold title="Record a paid operating expense"><DeskForm title="Actual operating expense" description="Include only expenses that were actually paid. Do not duplicate postage, call costs or closing expenses already recorded elsewhere." busy={busy} fields={[{ name: "category", label: "Category", required: true, placeholder: "Data subscription, counsel, hosting…" }, { name: "amount", label: "Amount paid ($)", type: "number", min: 0.01, step: 0.01, required: true }, occurredField, refField, { name: "synthetic", label: "Fictional practice expense", type: "checkbox" }]} submitLabel="Record paid expense" onSubmit={d => command({ type: "record_expense", category: textValue(d, "category"), amount: numberValue(d, "amount"), occurredAt: dateValue(d, "occurredAt"), reference: textValue(d, "reference"), synthetic: d.get("synthetic") === "on" }, "Operating expense recorded. Real expenses update spend and cost-per-result measures.")} /></Fold></Panel>
        <Panel title="A simple working rhythm"><div className="acq-steps">{[{ title: "Import & verify", body: "Bring in an authorized export. Resolve source and contact evidence.", tab: "import" as Tab }, { title: "Review & prepare", body: "Select the recipients and copy, then export an approved batch.", tab: "batches" as Tab }, { title: "Act & record", body: "Mail or dial manually. Log the real outcome and follow up.", tab: "batches" as Tab }, { title: "Contract & assign", body: "Record signed documents, match buyers and prepare a reviewed packet.", tab: "deals" as Tab }].map((item, i) => <button key={item.title} onClick={() => setTab(item.tab)}><span>{String(i + 1).padStart(2, "0")}</span><h3>{item.title}</h3><p>{item.body}</p></button>)}</div></Panel>
      </div>}

      {tab === "import" && <div className="acq-stack"><Panel title="Bring in an authorized seller export" description="Preview the mapped file before adding or updating any leads." action={<button className="btn btn-ghost" onClick={() => downloadFile({ filename: "sangam-seller-template.csv", mimeType: "text/csv;charset=utf-8", content: SOURCE_COLUMNS })}><ArrowDownToLine size={14} />CSV template</button>}>
        <form className="acq-form" onSubmit={async event => { event.preventDefault(); const data = new FormData(event.currentTarget); const input: ImportInput = { csv, source: textValue(data, "source"), sourceDate: textValue(data, "sourceDate"), permissionReference: textValue(data, "permissionReference"), synthetic: data.get("synthetic") === "on" }; setPreview(null); setImportInput(null); const result = await command({ type: "preview_import", ...input }, "Preview prepared. Review the rows before importing."); if (result) { setPreview(result as ImportPreview); setImportInput(input); } }}>
          <fieldset disabled={busy} className="acq-form-grid">
            <label className="acq-upload acq-span"><Upload size={24} /><strong>{fileName || "Choose a UTF-8 CSV export"}</strong><span>Mapped headers · maximum 1.8 MB · no spreadsheets or archives</span><input type="file" accept=".csv,text/csv" required onChange={async event => { setPreview(null); setImportInput(null); setCsv(""); const file = event.target.files?.[0]; setFileName(file?.name ?? ""); if (!file) return; if (file.size > 1_800_000) { setError("Choose a CSV no larger than 1.8 MB. If a file with many quoted fields exceeds the request limit, split it into smaller exports."); return; } try { setCsv(new TextDecoder("utf-8", { fatal: true }).decode(await file.arrayBuffer())); setError(""); } catch { setError("The file must be saved as UTF-8 CSV."); } }} /></label>
            <Field field={{ name: "source", label: "Source / saved list", required: true, placeholder: "PropStream · Tax distress · Riverside" }} /><Field field={{ name: "sourceDate", label: "Export date", type: "date", required: true }} />
            <Field field={{ name: "permissionReference", label: "Permission evidence reference", required: true, type: "textarea", hint: "Authorized account/entity, allowed use and the document or secure reference supporting this import." }} /><Field field={{ name: "synthetic", label: "These are fictional practice records", type: "checkbox", hint: "Use visibly fictional names/addresses, reserved 555-0100–0199 phones and example.com / .test emails. Practice exports cannot be delivered and never count toward the pilot." }} />
            <div className="acq-span"><button className="btn btn-primary" disabled={!csv} type="submit">Preview seller import<ArrowRight size={14} /></button></div>
          </fieldset>
        </form>
        <Fold title="What should be in the export?"><p className="acq-muted">Required: county, APN, property address and owner name. Add property ZIP, a complete owner mailing address, one selected phone, property type and any verified distress signals. Keep unknown values blank. Source permission does not establish permission to contact.</p><p className="acq-muted">Use the template headers exactly. Preserve APNs and ZIPs as text. A complete mailing address includes street, city, state and ZIP. Contact scrub results are recorded separately against the exact phone.</p><p className="acq-muted">This release supports Riverside and San Bernardino counties in the original 17 farm ZIPs. Records outside the farm can be researched but cannot enter an outreach batch.</p></Fold>
      </Panel>
      {preview && importInput && <Panel title="Review this import" description={`${preview.count} rows · ${preview.newCount} new · ${preview.updatedCount} updates · ${preview.eligibleScoreCount} score 8+`} action={<Pill tone={preview.synthetic ? "warn" : "muted"}>{preview.synthetic ? "Practice" : "Real data"}</Pill>}><div className="acq-table-wrap"><table><thead><tr><th>Property / owner</th><th>County · APN</th><th>Score</th><th>Review notes</th></tr></thead><tbody>{preview.rows.map((row, index) => <tr key={`${row.county}:${row.apn}:${index}`}><td><strong>{row.address}</strong><small>{row.ownerName}</small></td><td>{row.county}<small>{row.apn}</small></td><td><Pill tone={row.score >= 8 ? "good" : "muted"}>{row.score}</Pill></td><td>{row.warnings.join("; ") || "No import warning"}<small>{row.unknownSignals.length ? `Unknown: ${row.unknownSignals.map(humanize).join(", ")}` : "All scoring signals supplied"}</small></td></tr>)}</tbody></table></div><div className="acq-panel-footer"><p>Importing records will not mail, call or start the pilot clock.</p><button className="btn btn-primary" disabled={busy} onClick={async () => { const result = await command({ type: "import_leads", ...importInput, previewHash: preview.previewHash }, "Seller import committed. Review contact evidence before preparing a batch."); if (result !== undefined) { setPreview(null); setImportInput(null); setTab("leads"); } }}>Import reviewed rows<ArrowRight size={14} /></button></div></Panel>}
      </div>}

      {tab === "leads" && <div className="acq-stack"><Panel title="Seller leads" description="Score is seller motivation. It is separate from deal economics and buyer fit." action={<Pill>{selected.length} selected</Pill>}><div className="acq-toolbar"><label className="acq-search"><span className="sr-only">Search sellers</span><input type="search" placeholder="Search address, owner, APN or ZIP" value={search} onChange={event => setSearch(event.target.value)} /></label><button className="btn btn-ghost" onClick={() => setSelected(filteredLeads.filter(lead => lead.score >= 8).map(lead => lead.id))}>Select scores 8+</button><button className="acq-text-button" onClick={() => setSelected([])}>Clear</button><button className="btn btn-ghost" disabled={busy} onClick={() => void command({ type: "rescore" }, "Stored leads rescored. No new data was fetched or purchased.")}>Refresh scores</button><button className="btn btn-primary" disabled={!selected.length} onClick={() => setTab("batches")}>Prepare batch<ArrowRight size={14} /></button></div>
        {filteredLeads.length ? <div className="acq-table-wrap"><table><thead><tr><th><span className="sr-only">Select</span></th><th>Property / owner</th><th>Score</th><th>Contact evidence</th><th>Source</th><th></th></tr></thead><tbody>{filteredLeads.map(lead => { const suppressed = state.suppressions.some(item => item.leadId === lead.id || (item.phone && item.phone === lead.phone)); return <tr key={lead.id} className={focusedLeadId === lead.id ? "selected" : ""}><td><input type="checkbox" aria-label={`Select ${lead.address}`} checked={checked(lead.id)} onChange={() => toggle(lead.id)} /></td><td><button className="acq-cell-button" onClick={() => setFocusedLeadId(lead.id)}>{lead.address}</button><small>{lead.ownerName} · {lead.zip || "ZIP missing"}</small>{lead.synthetic && <Pill tone="warn">Practice</Pill>}</td><td><Pill tone={lead.score >= 8 ? "good" : "muted"}>{lead.score}</Pill></td><td>{suppressed ? <Pill tone="warn">Suppressed</Pill> : lead.contact ? <><Pill tone={lead.contact.dncStatus === "clear" && lead.contact.litigatorStatus === "clear" ? "good" : "warn"}>{lead.contact.dncStatus} / {lead.contact.litigatorStatus}</Pill><small>Scrub: {prettyDate(lead.contact.scrubbedAt)}</small></> : <Pill tone="warn">Needs evidence</Pill>}</td><td>{lead.source}<small>{lead.sourceDate}</small></td><td><button className="acq-icon-button" aria-label={`Open ${lead.address}`} onClick={() => setFocusedLeadId(lead.id)}><ChevronRight size={16} /></button></td></tr>; })}</tbody></table></div> : <Empty title="No seller leads yet">Import a mapped, authorized CSV to start building the queue.</Empty>}
      </Panel>
      {focused && <LeadDetail key={focused.id} lead={focused} state={state} busy={busy} command={command} />}
      </div>}

      {tab === "batches" && <div className="acq-stack"><div className="acq-columns"><Panel title="Prepare a manual batch" description="Select sellers in Seller leads, then choose reviewed content."><div className="acq-selection"><strong>{selectedLeads.length} sellers selected</strong><p>{selectedLeads.map(lead => lead.ownerName).slice(0, 6).join(", ") || "No recipients selected."}{selectedLeads.length > 6 ? ` + ${selectedLeads.length - 6} more` : ""}</p><button className="acq-text-button" onClick={() => setTab("leads")}>Choose seller leads<ArrowRight size={14} /></button></div><DeskForm title="Create batch draft" busy={busy || !selected.length} fields={[{ name: "templateId", label: "Reviewed template", type: "select", required: true, options: approvedTemplates.map(template => opt(template.id, `${channelLabel(template.channel)} · ${template.name} · v${template.revision}`)) }]} submitLabel="Create draft for review" onSubmit={async d => { const template = approvedTemplates.find(item => item.id === textValue(d, "templateId")); if (template) await command({ type: "draft_batch", templateId: template.id, channel: template.channel, leadIds: selected }, "Batch drafted. Review every recipient and the exact copy before approving."); }} /></Panel>
        <Panel title="Templates" description="A saved draft needs a reviewer before it can be used."><Fold title="Create a template" open={!state.templates.length}><DeskForm title="New template revision" busy={busy} fields={[{ name: "name", label: "Template name", required: true }, { name: "channel", label: "Channel", type: "select", required: true, options: [opt("mail", "Direct mail"), opt("call", "Manual calling")] }, { name: "body", label: "Exact message or call script", required: true, type: "textarea", hint: "Use reviewed copy and disclosures. Supported fields: {{owner_name}}, {{address}}, {{zip}}. A new save creates a revision." }]} submitLabel="Save draft" onSubmit={d => command({ type: "save_template", name: textValue(d, "name"), channel: textValue(d, "channel") as Channel, body: textValue(d, "body") }, "Template draft saved. A reviewer must approve it before use.")} /></Fold>{state.templates.map(template => <Fold key={template.id} title={`${template.name} · v${template.revision} · ${template.status}`}><Pill>{channelLabel(template.channel)}</Pill><pre className="acq-copy">{template.body}</pre>{reviewer && template.status !== "retired" && <DeskForm title={template.status === "draft" ? "Review this exact revision" : "Retire this revision"} busy={busy} fields={[evidenceField]} submitLabel={template.status === "draft" ? "Approve template" : "Retire template"} destructive={template.status === "approved"} onSubmit={d => command({ type: "review_template", templateId: template.id, approved: template.status === "draft", evidence: textValue(d, "evidence") })} />}</Fold>)}</Panel></div>
      <Panel title="Batch review & export" description="Approvals expire after 24 hours. Every download rechecks evidence, suppression and the approved snapshot.">{!state.batches.length ? <Empty title="No batch prepared">Select leads and a reviewed template to prepare the first draft.</Empty> : state.batches.slice().reverse().map(batch => <Fold key={batch.id} title={`${channelLabel(batch.channel)} · ${batch.items.length} recipients · ${batch.status} · ${prettyDate(batch.createdAt)}`}><div className="acq-toolbar"><Pill tone={batch.status === "approved" ? "good" : "muted"}>{batch.status}</Pill><span className="acq-muted">Approval expires: {prettyDate(batch.expiresAt)}</span></div><div className="acq-recipient-list">{batch.items.map(item => <details key={item.leadId}><summary>{item.ownerName}<span>{batch.channel === "mail" ? item.mailingAddress : item.phone}</span></summary><pre className="acq-copy">{item.content}</pre></details>)}</div>{batch.status === "draft" && reviewer && <DeskForm title="Approve the displayed recipients and content" description="Approval permits preparing this exact manual batch. It does not send anything." busy={busy} fields={[evidenceField]} submitLabel="Approve this batch" onSubmit={d => command({ type: "approve_batch", batchId: batch.id, evidence: textValue(d, "evidence") }, "Batch approved for 24 hours. Export rechecks all current evidence.")} />}{batch.status === "approved" && <div className="acq-panel-footer"><p>{batch.exportedAt.length} recorded exports. A download is not a touch.</p><button className="btn btn-primary" disabled={busy} onClick={() => void command({ type: "export_batch", batchId: batch.id }, "Manual batch downloaded. Record outcomes only after mailing or calling.")}><ArrowDownToLine size={16} />Download {batch.channel === "mail" ? "mail CSV" : "call sheet"}</button></div>}{batch.status !== "revoked" && <Fold title="Revoke this batch"><DeskForm title="Revoke approval" busy={busy} fields={[{ name: "reason", label: "Reason", required: true }]} submitLabel="Revoke batch" destructive onSubmit={d => command({ type: "revoke_batch", batchId: batch.id, reason: textValue(d, "reason") })} /></Fold>}</Fold>)}</Panel>
      <Panel title="Record what actually happened" description="Only actual, evidenced manual activity counts as a touch. Record one outcome per recipient."><div className="acq-form"><div className="acq-field"><label htmlFor="acq-receipt-batch">Exported batch</label><select id="acq-receipt-batch" className="acq-input" value={receiptBatchId} onChange={event => setReceiptBatchId(event.target.value)}><option value="">Choose an exported batch…</option>{state.batches.filter(batch => batch.exportedAt.length).map(batch => <option key={batch.id} value={batch.id}>{channelLabel(batch.channel)} · {batch.items.length} recipients · {prettyDate(batch.createdAt)}</option>)}</select></div></div>{receiptBatch && <DeskForm key={receiptBatch.id} title={receiptBatch.channel === "mail" ? "Mail receipt" : "Manual call outcome"} busy={busy} fields={[{ name: "leadId", label: "Recipient", required: true, type: "select", options: receiptBatch.items.map(item => opt(item.leadId, `${item.ownerName} · ${item.address}`)) }, occurredField, { name: "outcome", label: "Actual outcome", required: true, type: "select", options: (receiptBatch.channel === "mail" ? ["mailed"] : ["no_answer", "conversation", "appointment", "not_interested", "wrong_number", "opt_out"]).map(value => opt(value)) }, refField, { name: "cost", label: "Cost for this recipient ($)", type: "number", min: 0, step: 0.01, required: true }, { name: "notes", label: "Notes", type: "textarea" }]} submitLabel="Record actual outcome" onSubmit={d => command({ type: "record_receipt", batchId: receiptBatch.id, leadId: textValue(d, "leadId"), occurredAt: dateValue(d, "occurredAt"), outcome: textValue(d, "outcome") as "mailed", reference: textValue(d, "reference"), idempotencyKey: `${receiptBatch.id}:${textValue(d, "leadId")}`, cost: numberValue(d, "cost"), notes: textValue(d, "notes") }, "Actual outcome recorded. Pilot progress and follow-ups have been updated.")} />}</Panel>
      </div>}

      {tab === "deals" && <div className="acq-stack"><Panel title="Signed seller contracts" description="Qualify, underwrite and record the actual offer and signed purchase contract from a seller's detail page." action={<button className="btn btn-ghost" onClick={() => setTab("leads")}>Open seller leads<ArrowRight size={14} /></button>}>
        {state.contracts.length ? <div className="acq-table-wrap"><table><thead><tr><th>Property</th><th>Purchase price</th><th>Signed / closing</th><th>Stage</th><th></th></tr></thead><tbody>{state.contracts.map(contract => <tr key={contract.id}><td><strong>{leadName(contract.leadId)}</strong><small>{contract.reference}</small>{contract.synthetic && <Pill tone="warn">Practice</Pill>}</td><td><Money value={contract.price} /></td><td>{prettyDate(contract.signedAt)}<small>Closing {contract.closingDate}</small></td><td><Pill tone="good">{contract.termination ? "Cancelled" : state.closings.some(item => item.contractId === contract.id) ? "Closed" : state.assignments.some(item => item.contractId === contract.id) ? "Assigned" : "Contracted"}</Pill></td><td><button className="btn btn-ghost" disabled={busy || !!contract.termination} onClick={async () => { const result = await command({ type: "match_buyers", contractId: contract.id }, "Buyer matches prepared. Choose recipients for a reviewed manual packet."); if (Array.isArray(result)) { setMatches({ contractId: contract.id, buyers: result as BuyerMatch[] }); setPacketBuyers([]); } }}>Match buyers</button></td></tr>)}</tbody></table></div> : <Empty title="No signed contracts recorded">A real contract needs an offer, signed document reference, assignability and disclosure evidence.</Empty>}
      </Panel>
      {state.contracts.length > 0 && <Panel title="Contract updates" description="Record signed changes to keep buyer packets tied to the current agreement."><Fold title="Record a signed closing extension"><DeskForm title="Closing extension" busy={busy} fields={[{ name: "contractId", label: "Seller contract", type: "select", required: true, options: contractOptions }, { name: "newClosingDate", label: "New closing date", type: "date", required: true }, { name: "signedAt", label: "Actual amendment signed time", type: "datetime-local", required: true }, refField]} submitLabel="Record signed extension" onSubmit={d => command({ type: "extend_contract", contractId: textValue(d, "contractId"), newClosingDate: textValue(d, "newClosingDate"), signedAt: dateValue(d, "signedAt"), reference: textValue(d, "reference") }, "Contract extension recorded. Prepare and review a new buyer packet for the changed agreement.")} /></Fold><Fold title="Record cancellation or termination"><DeskForm title="Contract termination" busy={busy} fields={[{ name: "contractId", label: "Seller contract", type: "select", required: true, options: contractOptions }, { name: "endedAt", label: "Actual termination time", type: "datetime-local", required: true }, refField, { name: "reason", label: "Reason", required: true, type: "textarea" }]} submitLabel="Record terminated contract" destructive onSubmit={d => command({ type: "cancel_contract", contractId: textValue(d, "contractId"), endedAt: dateValue(d, "endedAt"), reference: textValue(d, "reference"), reason: textValue(d, "reason") }, "Contract termination recorded. Buyer packets for this agreement are held.")} /></Fold></Panel>}
      <div className="acq-columns"><Panel title="Buyer buy-boxes" description="Use contacts with documented permission and keep their preferences current."><Fold title="Add a buyer" open={!state.buyers.length}><BuyerForm busy={busy} command={command} /></Fold>{state.buyers.map(buyer => <Fold key={buyer.id} title={`${buyer.name} · ${buyer.active ? "active" : "inactive"}${buyer.synthetic ? " · practice" : ""}`}><dl className="acq-facts"><div><dt>Contact</dt><dd>{buyer.email || buyer.phone}</dd></div><div><dt>Buy box</dt><dd><Money value={buyer.minPrice} />–<Money value={buyer.maxPrice} /></dd></div><div><dt>Target ZIPs</dt><dd>{buyer.zips.join(", ")}</dd></div><div><dt>Types</dt><dd>{buyer.propertyTypes.join(", ")}</dd></div><div><dt>Permission</dt><dd>{buyer.permissionReference}</dd></div></dl><BuyerForm buyer={buyer} busy={busy} command={command} /></Fold>)}</Panel>
      <Panel title="Prepare a buyer packet" description="Only manually selected buyers receive an exported packet. Nothing is sent automatically.">{matches ? <><div className="acq-selection"><strong>{contractName(matches.contractId)}</strong><p>Fit ranks current price, ZIP, property type and rehab preferences. Review the details before selecting.</p></div>{matches.buyers.length ? <div className="acq-matches">{matches.buyers.map(match => <label key={match.buyerId}><input type="checkbox" checked={packetBuyers.includes(match.buyerId)} onChange={() => setPacketBuyers(ids => ids.includes(match.buyerId) ? ids.filter(id => id !== match.buyerId) : [...ids, match.buyerId])} /><span><strong>{match.name}</strong><small>{match.reasons.join(" · ")}</small></span><Pill>{match.score} fit</Pill></label>)}</div> : <p className="acq-empty">No eligible buyers match this contract. Add or update a permitted buy-box.</p>}<DeskForm title="Exact packet content" busy={busy || !packetBuyers.length} fields={[{ name: "body", label: "Assignment-interest packet", type: "textarea", required: true, hint: "Describe your contractual interest, asking assignment terms, property facts and the approved disclosures. Reference private documents securely." }]} submitLabel="Draft packet for review" onSubmit={d => command({ type: "draft_packet", contractId: matches.contractId, buyerIds: packetBuyers, body: textValue(d, "body") }, "Buyer packet drafted. A reviewer must approve the exact recipients and content.")} /></> : <Empty title="Start from a signed contract">Choose Match buyers on a contracted seller lead to see ranked buy-boxes.</Empty>}</Panel></div>
      <Panel title="Review & export buyer packets" description="Each approval is bound to the contract, buyers and exact packet content.">{!state.packets.length ? <Empty title="No buyer packets prepared">Match a signed contract and select buyers to create one.</Empty> : state.packets.slice().reverse().map(packet => <Fold key={packet.id} title={`${contractName(packet.contractId)} · ${packet.buyerIds.length} buyers · ${packet.status}`}><p className="acq-muted">Recipients: {packet.buyerIds.map(buyerName).join(", ")}</p><pre className="acq-copy">{packet.body}</pre><p className="acq-muted">Approval expires: {prettyDate(packet.expiresAt)}</p>{packet.status === "draft" && reviewer && <DeskForm title="Review this exact packet" busy={busy} fields={[evidenceField]} submitLabel="Approve packet" onSubmit={d => command({ type: "approve_packet", packetId: packet.id, evidence: textValue(d, "evidence") })} />}{packet.status === "approved" && <button className="btn btn-primary" disabled={busy} onClick={() => void command({ type: "export_packet", packetId: packet.id }, "Buyer packet downloaded. Deliver it manually and record the actual receipt.")}><ArrowDownToLine size={15} />Download manual packet</button>}{packet.status !== "revoked" && <Fold title="Revoke packet"><DeskForm title="Revoke this packet" busy={busy} fields={[{ name: "reason", label: "Reason", required: true }]} submitLabel="Revoke packet" destructive onSubmit={d => command({ type: "revoke_packet", packetId: packet.id, reason: textValue(d, "reason") })} /></Fold>}</Fold>)}</Panel>
      <div className="acq-columns"><Panel title="Record manual buyer delivery" description="Delivery receipts support the 24-hour buyer alert target."><div className="acq-form"><div className="acq-field"><label htmlFor="acq-receipt-packet">Exported packet</label><select id="acq-receipt-packet" className="acq-input" value={receiptPacketId} onChange={event => setReceiptPacketId(event.target.value)}><option value="">Choose an exported packet…</option>{state.packets.filter(packet => packet.exportedAt.length).map(packet => <option key={packet.id} value={packet.id}>{contractName(packet.contractId)} · {packet.buyerIds.length} buyers</option>)}</select></div></div>{receiptPacket && <DeskForm key={receiptPacket.id} title="Actual buyer outcome" busy={busy} fields={[{ name: "buyerId", label: "Buyer", required: true, type: "select", options: receiptPacket.buyerIds.map(id => opt(id, buyerName(id))) }, occurredField, { name: "outcome", label: "Outcome", required: true, type: "select", options: ["delivered", "interested", "declined", "opt_out"].map(value => opt(value)) }, refField]} submitLabel="Record buyer outcome" onSubmit={d => command({ type: "record_buyer_receipt", packetId: receiptPacket.id, buyerId: textValue(d, "buyerId"), occurredAt: dateValue(d, "occurredAt"), outcome: textValue(d, "outcome") as "delivered", reference: textValue(d, "reference"), idempotencyKey: `${receiptPacket.id}:${textValue(d, "buyerId")}:${textValue(d, "outcome")}` })} />}</Panel>
      <Panel title="Assignment & closing" description="Record signed agreements and actual closing receipts only."><Fold title="Record a signed assignment"><DeskForm title="Assignment evidence" busy={busy} fields={[{ name: "contractId", label: "Seller contract", type: "select", required: true, options: contractOptions }, { name: "buyerId", label: "End buyer", type: "select", required: true, options: state.buyers.map(buyer => opt(buyer.id, buyer.name)) }, { name: "signedAt", label: "Assignment signed at", type: "datetime-local", required: true }, { name: "price", label: "Assignment contract price ($)", type: "number", min: 0, step: 0.01, required: true }, refField, { name: "disclosuresReference", label: "Buyer disclosure evidence", required: true }, { name: "depositAmount", label: "Deposit held ($)", type: "number", min: 0, step: 0.01, required: true }, { name: "depositReference", label: "Deposit / escrow reference", required: true }]} submitLabel="Record signed assignment" onSubmit={d => command({ type: "record_assignment", contractId: textValue(d, "contractId"), buyerId: textValue(d, "buyerId"), signedAt: dateValue(d, "signedAt"), price: numberValue(d, "price"), reference: textValue(d, "reference"), disclosuresReference: textValue(d, "disclosuresReference"), depositAmount: numberValue(d, "depositAmount"), depositReference: textValue(d, "depositReference") })} /></Fold><Fold title="Record actual closing"><DeskForm title="Closing receipt" busy={busy} fields={[{ name: "contractId", label: "Seller contract", type: "select", required: true, options: contractOptions }, { name: "closedAt", label: "Actual closing time", type: "datetime-local", required: true }, { name: "assignmentFee", label: "Assignment fee collected ($)", type: "number", min: 0, step: 0.01, required: true }, { name: "expenses", label: "Other closing expenses ($)", type: "number", min: 0, step: 0.01, required: true }, refField]} submitLabel="Record closing" onSubmit={d => command({ type: "record_close", contractId: textValue(d, "contractId"), closedAt: dateValue(d, "closedAt"), assignmentFee: numberValue(d, "assignmentFee"), expenses: numberValue(d, "expenses"), reference: textValue(d, "reference") }, "Actual closing recorded. Collected fees and expenses are included in pilot results.")} /></Fold></Panel></div>
      </div>}

      {tab === "readiness" && <div className="acq-stack"><div className="acq-info"><CircleHelp size={20} /><p>Record the evidence that already exists. A checkbox in this product is not professional approval. Reviewers and administrators can record or block gates; operators can inspect them.</p></div><Panel title="Launch evidence" description="General gates apply to each manual export. The pre-foreclosure gate applies only to NOD leads.">{GATES.map(gate => { const record = state.gates.find(item => item.name === gate.id); const expired = record?.expiresAt && new Date(record.expiresAt).getTime() <= Date.now(); return <Fold key={gate.id} title={`${gate.label} · ${expired ? "expired" : record?.status ?? "missing"}`} open={summary.nextBlockedGate === gate.id}><p className="acq-muted">{gate.need}</p>{record && <dl className="acq-facts"><div><dt>Evidence</dt><dd>{record.evidence}</dd></div><div><dt>Reviewed</dt><dd>{prettyDate(record.reviewedAt)}</dd></div><div><dt>Expires</dt><dd>{record.expiresAt ? prettyDate(record.expiresAt) : "No expiry recorded"}</dd></div><div><dt>Recorded by</dt><dd>{record.reviewerId}</dd></div></dl>}{reviewer && <DeskForm title="Record a review" busy={busy} fields={[{ name: "status", label: "Review decision", type: "select", required: true, options: [opt("approved", "Approved with evidence"), opt("blocked", "Blocked / withdrawn")] }, { name: "reviewedAt", label: "Actual review time", type: "datetime-local", required: true }, evidenceField, { name: "expiresAt", label: "Expiry time, if applicable", type: "datetime-local" }]} submitLabel="Save review record" onSubmit={d => command({ type: "set_gate", gate: gate.id, status: textValue(d, "status") as "approved" | "blocked", evidence: textValue(d, "evidence"), reviewedAt: dateValue(d, "reviewedAt"), expiresAt: textValue(d, "expiresAt") ? dateValue(d, "expiresAt") : null }, "Review evidence recorded. Existing batches will be rechecked before export.")} />}</Fold>; })}</Panel><Panel title="Activity record" description="Recent changes in this workspace. Operational data stays inside this workspace.">{state.audit.length ? <div className="acq-table-wrap"><table><thead><tr><th>Action</th><th>When</th><th>Actor</th><th>Detail</th></tr></thead><tbody>{state.audit.slice(-50).reverse().map(item => <tr key={item.id}><td>{humanize(item.action)}</td><td>{prettyDate(item.at)}</td><td>{item.actorId}</td><td>{item.detail}</td></tr>)}</tbody></table></div> : <Empty title="No activity yet">Imports, reviews and actual outcomes will build the audit record.</Empty>}</Panel></div>}
      <footer className="acq-footer"><span><ShieldCheck size={13} />Workspace access and evidence are checked on the server.</span><span>Manual release · v1</span></footer>
    </>}
  </div>;
}

function Metric({ label, value, goal }: { label: string; value: React.ReactNode; goal?: number }) {
  return <div className="acq-metric"><span>{label}</span><strong>{value}{goal && <small> / {goal.toLocaleString()}</small>}</strong>{typeof value === "number" && goal && <div className="acq-progress"><i style={{ width: `${Math.min(value / goal * 100, 100)}%` }} /></div>}</div>;
}

type CommandRunner = (command: Command, success?: string) => Promise<unknown>;
function LeadDetail({ lead, state, busy, command }: { lead: Lead; state: AcquisitionState; busy: boolean; command: CommandRunner }) {
  const offers = state.offers.filter(offer => offer.leadId === lead.id);
  const suppressed = state.suppressions.some(item => item.leadId === lead.id || (item.phone && item.phone === lead.phone));
  return <Panel title={lead.address} description={`${lead.ownerName} · ${lead.county} · APN ${lead.apn}`} action={<Pill tone={lead.synthetic ? "warn" : "muted"}>{lead.synthetic ? "Practice record" : "Real lead"}</Pill>}>
    <div className="acq-detail-overview"><dl className="acq-facts"><div><dt>Mailing address</dt><dd>{lead.mailingAddress || "Missing"}</dd></div><div><dt>Phone</dt><dd>{lead.phone || "Missing"}</dd></div><div><dt>Property type</dt><dd>{lead.propertyType || "Unknown"}</dd></div><div><dt>Source permission</dt><dd>{lead.permissionReference}</dd></div></dl><div className="acq-signals"><h3>Seller motivation · {lead.score} points</h3>{Object.entries(lead.signals).map(([key, value]) => <div key={key}><span>{humanize(key)}</span><strong>{value === null ? "Unknown" : typeof value === "boolean" ? value ? "Yes" : "No" : value}</strong></div>)}</div></div>
    {suppressed && <div className="acq-alert acq-alert-error"><strong>This contact is permanently suppressed.</strong><p>Existing and future exports will check the shared suppression record.</p></div>}
    <Fold title="Contact & scrub evidence" open={!lead.contact}><DeskForm title="Record evidence for the exact phone" description="A phone result must be clear on both checks and current. Manual calls also require evidence of the recipient's timezone." busy={busy} fields={[{ name: "phone", label: "Selected phone", type: "tel", required: true, value: lead.phone }, { name: "dncStatus", label: "DNC result", type: "select", required: true, options: ["unknown", "clear", "blocked"].map(value => opt(value)) }, { name: "litigatorStatus", label: "Litigator result", type: "select", required: true, options: ["unknown", "clear", "blocked"].map(value => opt(value)) }, { name: "scrubbedAt", label: "Actual scrub time", type: "datetime-local", required: true }, { name: "recipientTimezone", label: "Recipient timezone", placeholder: "America/Los_Angeles", hint: "Required for manual calling; leave blank when unverified." }, { name: "timezoneEvidence", label: "Timezone evidence", hint: "Record how the recipient's location was established; do not infer it from the property alone." }, { name: "evidenceReference", label: "Scrub provider / report reference", required: true }]} submitLabel="Record contact evidence" onSubmit={d => command({ type: "record_contact", leadId: lead.id, phone: textValue(d, "phone"), dncStatus: textValue(d, "dncStatus") as "clear", litigatorStatus: textValue(d, "litigatorStatus") as "clear", scrubbedAt: dateValue(d, "scrubbedAt"), recipientTimezone: textValue(d, "recipientTimezone"), timezoneEvidence: textValue(d, "timezoneEvidence"), evidenceReference: textValue(d, "evidenceReference") })} /></Fold>
    <Fold title="Record an inbound seller response"><DeskForm title="Actual seller response" description="Use this for a reply to mail or a later inbound call. It records a response without inventing another outbound touch." busy={busy} fields={[occurredField, { name: "outcome", label: "Response outcome", type: "select", required: true, options: ["conversation", "appointment", "not_interested", "wrong_number", "opt_out"].map(value => opt(value)) }, refField, { name: "notes", label: "Response notes", type: "textarea" }]} submitLabel="Record actual response" onSubmit={d => command({ type: "record_response", leadId: lead.id, occurredAt: dateValue(d, "occurredAt"), outcome: textValue(d, "outcome") as "conversation", reference: textValue(d, "reference"), notes: textValue(d, "notes") }, "Seller response recorded. Opt-out responses suppress future outreach.")} /></Fold>
    <Fold title="Qualification"><DeskForm title="Record a seller conversation" busy={busy} fields={[{ name: "condition", label: "Property condition", required: true, value: lead.qualification?.condition }, { name: "timeline", label: "Seller timeline", required: true, value: lead.qualification?.timeline }, { name: "priceExpectation", label: "Seller price expectation ($)", type: "number", min: 0, step: 0.01, value: lead.qualification?.priceExpectation ?? "" }, { name: "mortgageBalance", label: "Mortgage balance, if known ($)", type: "number", min: 0, step: 0.01, value: lead.qualification?.mortgageBalance ?? "" }, { name: "notes", label: "Conversation notes", type: "textarea", value: lead.qualification?.notes }]} submitLabel="Save qualification" onSubmit={d => command({ type: "qualify_lead", leadId: lead.id, condition: textValue(d, "condition"), timeline: textValue(d, "timeline"), priceExpectation: optionalNumber(d, "priceExpectation"), mortgageBalance: optionalNumber(d, "mortgageBalance"), notes: textValue(d, "notes") })} /></Fold>
    <Fold title="Comps & maximum offer">{lead.underwriting && <div className="acq-selection"><strong>Calculated maximum offer: <Money value={lead.underwriting.mao} /></strong><p>Review the comp evidence and costs before recording an actual offer.</p></div>}<DeskForm title="Manual underwriting" description="Use at least three comparable sold properties. The result is a planning calculation, not an appraisal." busy={busy} fields={[{ name: "arv", label: "After-repair value ($)", type: "number", min: 0, required: true, value: lead.underwriting?.arv }, { name: "repairs", label: "Estimated repairs ($)", type: "number", min: 0, required: true, value: lead.underwriting?.repairs }, { name: "closingCosts", label: "Closing / holding costs ($)", type: "number", min: 0, required: true, value: lead.underwriting?.closingCosts }, { name: "assignmentFee", label: "Target assignment fee ($)", type: "number", min: 0, required: true, value: lead.underwriting?.assignmentFee }, { name: "profitPercent", label: "Buyer margin (%)", type: "number", min: 10, max: 50, step: 0.1, required: true, value: lead.underwriting ? lead.underwriting.profitPercent * 100 : undefined, hint: "Enter 10–50. The margin is deducted from ARV before repairs, costs and fee." }, { name: "compReferences", label: "Sold comp references", type: "textarea", required: true, value: lead.underwriting?.compReferences.join("\n"), hint: "One reference per line, at least three. Include sale date, price and why it is comparable." }]} submitLabel="Calculate & save maximum offer" onSubmit={d => command({ type: "underwrite", leadId: lead.id, arv: numberValue(d, "arv"), repairs: numberValue(d, "repairs"), closingCosts: numberValue(d, "closingCosts"), assignmentFee: numberValue(d, "assignmentFee"), profitPercent: numberValue(d, "profitPercent") / 100, compReferences: textValue(d, "compReferences").split("\n").map(value => value.trim()).filter(Boolean) })} /></Fold>
    <Fold title="Actual offers & signed contract">{offers.length > 0 && <div className="acq-list">{offers.map(offer => <div key={offer.id} className="acq-list-row"><span><strong><Money value={offer.amount} /></strong><small>{prettyDate(offer.occurredAt)} · {offer.reference}</small></span></div>)}</div>}<DeskForm title="Record an offer you actually made" busy={busy} fields={[{ name: "amount", label: "Offer amount ($)", type: "number", required: true, min: 0 }, occurredField, refField]} submitLabel="Record actual offer" onSubmit={d => command({ type: "record_offer", leadId: lead.id, amount: numberValue(d, "amount"), occurredAt: dateValue(d, "occurredAt"), reference: textValue(d, "reference") })} /><DeskForm title="Record a signed seller contract" busy={busy} fields={[{ name: "offerId", label: "Accepted offer", type: "select", required: true, options: offers.map(offer => opt(offer.id, `$${offer.amount.toLocaleString()} · ${offer.reference}`)) }, { name: "price", label: "Signed purchase price ($)", type: "number", required: true, min: 0 }, { name: "signedAt", label: "Actual signed time", type: "datetime-local", required: true }, { name: "closingDate", label: "Contract closing date", type: "date", required: true }, refField, { name: "disclosuresReference", label: "Seller disclosure delivery evidence", required: true }, { name: "assignable", label: "The signed contract explicitly permits assignment", type: "checkbox", required: true }]} submitLabel="Record signed contract" onSubmit={d => command({ type: "record_contract", leadId: lead.id, offerId: textValue(d, "offerId"), price: numberValue(d, "price"), signedAt: dateValue(d, "signedAt"), closingDate: textValue(d, "closingDate"), reference: textValue(d, "reference"), disclosuresReference: textValue(d, "disclosuresReference"), assignable: d.get("assignable") === "on" })} /></Fold>
    {!suppressed && <Fold title="Suppress this contact"><DeskForm title="Permanently suppress" description="Use this for opt-outs and other requests to stop contact. Suppression is shared across channels and checked at every export." busy={busy} fields={[{ name: "reason", label: "Reason / request reference", required: true }]} submitLabel="Suppress contact" destructive onSubmit={d => command({ type: "suppress", leadId: lead.id, reason: textValue(d, "reason") }, "Contact suppressed. It cannot enter another outreach export.")} /></Fold>}
    <Fold title="Actual touch history">{state.receipts.filter(item => item.leadId === lead.id).length ? <div className="acq-list">{state.receipts.filter(item => item.leadId === lead.id).map(receipt => <div key={receipt.id} className="acq-list-row"><span><strong>{channelLabel(receipt.channel)} · {humanize(receipt.outcome)}</strong><small>{prettyDate(receipt.occurredAt)} · {receipt.reference}</small></span><Money value={receipt.cost} /></div>)}</div> : <p className="acq-muted">No actual touch recorded.</p>}</Fold>
  </Panel>;
}

function BuyerForm({ buyer, busy, command }: { buyer?: AcquisitionState["buyers"][number]; busy: boolean; command: CommandRunner }) {
  return <DeskForm title={buyer ? "Update this buyer" : "Permitted buyer contact"} busy={busy} fields={[{ name: "name", label: "Buyer / entity name", required: true, value: buyer?.name }, { name: "email", label: "Email", type: "email", value: buyer?.email }, { name: "phone", label: "Phone", type: "tel", value: buyer?.phone }, { name: "zips", label: "Target ZIPs", required: true, value: buyer?.zips.join(", "), hint: "Comma-separated ZIPs." }, { name: "minPrice", label: "Minimum price ($)", required: true, type: "number", min: 0, value: buyer?.minPrice }, { name: "maxPrice", label: "Maximum price ($)", required: true, type: "number", min: 0, value: buyer?.maxPrice }, { name: "propertyTypes", label: "Property types", required: true, value: buyer?.propertyTypes.join(", "), hint: "Comma-separated values matching seller records, e.g. SFR, condo, small multi." }, { name: "rehabMax", label: "Maximum rehab ($), if known", type: "number", min: 0, value: buyer?.rehabMax ?? "" }, { name: "cashPurchases24m", label: "Verified cash purchases in 24 months", type: "number", min: 0, step: 1, value: buyer?.cashPurchases24m ?? "", hint: "Leave blank if unknown." }, { name: "lastCashPurchaseDate", label: "Last verified cash purchase date", type: "date", value: buyer?.lastCashPurchaseDate ?? "" }, { name: "purchasedFarmZip", label: "Verified purchase in a farm ZIP", type: "select", value: buyer?.purchasedFarmZip == null ? "" : String(buyer.purchasedFarmZip), options: [opt("true", "Yes, a documented purchase"), opt("false", "No")], hint: "Past purchases, separate from preferred ZIPs. Leave blank if unknown." }, { name: "entity", label: "Entity buyer", type: "select", value: buyer?.entity == null ? "" : String(buyer.entity), options: [opt("true", "Yes, LLC / corporation"), opt("false", "No")], hint: "Leave unselected if unknown. Cite evidence below." }, { name: "sourceReference", label: "Source / permitted use reference", required: true, value: buyer?.sourceReference }, { name: "permissionReference", label: "Buyer contact permission evidence", required: true, value: buyer?.permissionReference }, { name: "permissionAt", label: "Actual permission date & time", type: "datetime-local", required: true }, { name: "active", label: "Buyer status", type: "select", required: true, value: buyer ? String(buyer.active) : "", options: [opt("true", "Active / permission current"), opt("false", "Inactive / no further contact")] }, ...(!buyer ? [{ name: "synthetic", label: "Fictional practice buyer", type: "checkbox" as const }] : [])]} submitLabel={buyer ? "Update buyer" : "Add buyer"} onSubmit={d => command({ type: "save_buyer", ...(buyer ? { id: buyer.id } : {}), name: textValue(d, "name"), email: textValue(d, "email"), phone: textValue(d, "phone"), zips: listValue(d, "zips"), minPrice: numberValue(d, "minPrice"), maxPrice: numberValue(d, "maxPrice"), propertyTypes: listValue(d, "propertyTypes"), rehabMax: optionalNumber(d, "rehabMax"), sourceReference: textValue(d, "sourceReference"), permissionReference: textValue(d, "permissionReference"), permissionAt: dateValue(d, "permissionAt"), active: textValue(d, "active") === "true", cashPurchases24m: optionalNumber(d, "cashPurchases24m"), purchasedFarmZip: textValue(d, "purchasedFarmZip") === "" ? null : textValue(d, "purchasedFarmZip") === "true", lastCashPurchaseDate: textValue(d, "lastCashPurchaseDate") || null, entity: textValue(d, "entity") === "" ? null : textValue(d, "entity") === "true", synthetic: buyer?.synthetic ?? d.get("synthetic") === "on" })} />;
}
